import torch
import torch.nn as nn
from torch.utils.data import Dataset

def make_dataset(events, pre, train: bool):
    return AugmentedEventDataset(events, pre, train)

class AugmentedEventDataset(Dataset):
    def __init__(self, events, pre, train=True):
        self.events = events
        self.pre = pre
        self.train = train
    def __len__(self):
        return len(self.events)
    def __getitem__(self, idx):
        X, y = _split_X_y(self.events[idx])                     # X: [N_i,4], y: [N_i]
        y_float = y.unsqueeze(1).to(X.dtype)                     # [N_i,1]
        X_aug = torch.cat([X, y_float], dim=1)                   # [N_i,5]
        if self.pre is not None:
            X_feat = self.pre.transform(X_aug[:, :-1])           # [N_i,4]
            X_aug = torch.cat([X_feat, X_aug[:, -1:]], dim=1)    # [N_i,5]
        return X_aug, y

