class HitClassifier(nn.Module):
    def __init__(self, in_features, num_classes):
        super().__init__()
        self.in_features = in_features
        self.num_classes = num_classes
    def forward(self, batch_x):
        # batch_x: [N_hits, in_features] where last feature is true track_id
        y_true = batch_x[:, -1].long()                         # [N_hits]
        N = y_true.size(0)
        logits = batch_x.new_zeros((N, self.num_classes))      # [N_hits, num_classes]
        logits[torch.arange(N, device=logits.device), y_true] = 1.0
        return logits

def make_model(input_features):
    if isinstance(input_features, torch.Tensor):
        in_feats = input_features.shape[1]
    else:
        in_feats = int(input_features)
    return HitClassifier(in_feats, NUM_CLASSES)

